Draw() {
        MultiplePiePlot plot = new MultiplePiePlot();
        JFreeChart chart = new JFreeChart(plot);
        BufferedImage image = new BufferedImage(500, 250,
                BufferedImage.TYPE_INT_RGB);
        Graphics2D g2 = image.createGraphics();
        chart.draw(g2, new Rectangle2D.Double(0, 0, 500, 250), null, null);
        g2.dispose();
        assertThat(image.getRGB(0, 0), is(Color.white.getRGB()));
        assertThat(image.getRGB(499, 0), is(Color.green.getRGB()));
        assertThat(image.getRGB(499, 499), is(Color.white.getRGB()));
    }

